-- Sales orders: the master record of every order, plus one line per product.
--
-- Named sales_orders / sales_order_lines so the unused legacy `orders` table can stay
-- exactly as it is. Rows are written only through the functions in
-- 20261017000600_order_functions.sql; partners can read them.

create table public.sales_orders (
  id bigint generated always as identity primary key,
  -- Generated by the order form once per submission and reused on every retry, so a
  -- double click or a resubmit after an error can never create a second order.
  idempotency_key text not null,
  order_date date not null default ((now() at time zone 'America/Los_Angeles')::date),
  customer_id bigint references public.customers (id) on delete restrict,
  customer_name text not null,
  type text not null default 'business',
  delivery_type text not null,
  delivery_date date,
  po_number text,
  notes text,
  total_cans integer not null default 0,
  total_price numeric(10, 2) not null default 0,
  is_paid boolean not null default false,
  create_invoice boolean not null default false,
  is_donation boolean not null default false,
  sheet_status text not null default 'pending',
  sheet_error text,
  inventory_status text not null default 'pending',
  inventory_error text,
  trello_status text not null default 'pending',
  trello_error text,
  trello_card_id text,
  square_status text not null default 'pending',
  square_error text,
  square_invoice_id text,
  voided_at timestamptz,
  voided_by uuid references auth.users (id) on delete set null,
  void_reason text,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint sales_orders_idempotency_key_key unique (idempotency_key),
  constraint sales_orders_idempotency_key_valid
    check (idempotency_key ~ '^\S+$' and length(idempotency_key) <= 200),
  constraint sales_orders_customer_name_trimmed check (customer_name ~ '^\S(.*\S)?$'),
  constraint sales_orders_type_valid check (type in ('business', 'individual')),
  constraint sales_orders_delivery_type_valid check (delivery_type in ('drop', 'ship', 'pickup')),
  constraint sales_orders_totals_valid check (total_cans >= 0 and total_price >= 0),
  constraint sales_orders_donation_is_free check (not is_donation or total_price = 0),
  constraint sales_orders_sheet_status_valid
    check (sheet_status in ('pending', 'done', 'failed', 'skipped')),
  constraint sales_orders_inventory_status_valid
    check (inventory_status in ('pending', 'done', 'failed', 'skipped')),
  constraint sales_orders_trello_status_valid
    check (trello_status in ('pending', 'done', 'failed', 'skipped')),
  constraint sales_orders_square_status_valid
    check (square_status in ('pending', 'done', 'failed', 'skipped')),
  constraint sales_orders_trello_done_has_card
    check (trello_status <> 'done' or trello_card_id is not null),
  constraint sales_orders_square_done_has_invoice
    check (square_status <> 'done' or square_invoice_id is not null),
  constraint sales_orders_void_has_reason check ((voided_at is null) = (void_reason is null))
);

-- One Trello card and one Square invoice per order, never shared.
create unique index sales_orders_trello_card_id_key on public.sales_orders (trello_card_id)
  where trello_card_id is not null;
create unique index sales_orders_square_invoice_id_key on public.sales_orders (square_invoice_id)
  where square_invoice_id is not null;
create index sales_orders_customer_id_idx on public.sales_orders (customer_id)
  where customer_id is not null;
create index sales_orders_order_date_idx on public.sales_orders (order_date, lower(customer_name));

create trigger sales_orders_touch_updated_at
  before update on public.sales_orders
  for each row execute function private.touch_updated_at();

comment on table public.sales_orders is
  'One row per order. Each downstream step (sheet, inventory, Trello, Square) records its own status so a failed step can be retried without repeating the others.';
comment on column public.sales_orders.order_date is 'Order date in Portland time (the Sales sheet''s Date).';
comment on column public.sales_orders.customer_name is
  'Customer name as it was when the order was placed (kept even if the customer is renamed).';
comment on column public.sales_orders.po_number is
  'The customer''s purchase order number, when they send one (Sysco does, per order).';
comment on column public.sales_orders.total_price is
  'What the customer is charged, in dollars. Can differ from the sum of line totals by rounding or a manual price.';
comment on column public.sales_orders.inventory_status is
  'Set by apply_order_inventory (done or skipped) or record_order_step (failed).';

create table public.sales_order_lines (
  id bigint generated always as identity primary key,
  order_id bigint not null references public.sales_orders (id) on delete cascade,
  product text not null,
  cans integer not null,
  batch_id bigint not null references public.inventory (id) on delete restrict,
  -- Copied from the batch by a trigger: a line is custom only if its cans really are.
  is_custom boolean not null default false,
  unit_price numeric(10, 4) not null,
  line_total numeric(10, 2) generated always as (round(cans * unit_price, 2)) stored,
  created_at timestamptz not null default now(),
  constraint sales_order_lines_product_valid check (product in ('still', 'sparkling', 'dog_water')),
  constraint sales_order_lines_cans_positive check (cans > 0),
  constraint sales_order_lines_unit_price_valid check (unit_price >= 0)
);

create index sales_order_lines_order_id_idx on public.sales_order_lines (order_id);
create index sales_order_lines_batch_id_idx on public.sales_order_lines (batch_id);

comment on table public.sales_order_lines is 'Products on an order. Each line draws its cans from one inventory batch.';
comment on column public.sales_order_lines.unit_price is 'Price per can in dollars.';

-- A line must draw from a live batch of the right product, and takes is_custom from it.
create function private.orders_line_from_batch()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_batch record;
begin
  select i.name, i."isStill" as is_still, i."isCustom" as is_custom, i.product, i.archived_at
  into v_batch
  from public.inventory i
  where i.id = new.batch_id;

  if not found then
    raise exception 'Inventory batch % does not exist', new.batch_id
      using errcode = 'P0001', hint = 'batch_not_found';
  end if;

  if v_batch.archived_at is not null then
    raise exception 'Inventory batch % (%) is archived', new.batch_id, v_batch.name
      using errcode = 'P0001', hint = 'batch_archived';
  end if;

  if not (
    (new.product = 'still' and v_batch.product = 'water' and coalesce(v_batch.is_still, false))
    or (new.product = 'sparkling' and v_batch.product = 'water' and not coalesce(v_batch.is_still, true))
    or (new.product = 'dog_water' and v_batch.product = 'dog_water')
  ) then
    raise exception 'Inventory batch % (%) cannot fill a % line', new.batch_id, v_batch.name, new.product
      using errcode = 'P0001', hint = 'product_batch_mismatch';
  end if;

  new.is_custom := coalesce(v_batch.is_custom, false);
  return new;
end
$$;

revoke execute on function private.orders_line_from_batch() from public;

create trigger sales_order_lines_from_batch
  before insert or update of batch_id, product on public.sales_order_lines
  for each row execute function private.orders_line_from_batch();

alter table public.sales_orders enable row level security;
alter table public.sales_order_lines enable row level security;

create policy "Partners read sales orders"
  on public.sales_orders
  for select
  to authenticated
  using ((select public.is_partner()));

create policy "Partners read sales order lines"
  on public.sales_order_lines
  for select
  to authenticated
  using ((select public.is_partner()));

revoke all on table public.sales_orders, public.sales_order_lines from anon, authenticated;
grant select on table public.sales_orders, public.sales_order_lines to authenticated;
